[[ -f "$PY" ]] || { warn "Falta $PY (ln -s do .venv do checkout principal)."; exit 1; }
[[ -f .env ]] || { warn "Falta o .env (cp do checkout principal)."; exit 1; }

# ── 2. Reautenticar o gcloud ─────────────────────────────────────────────
stage "Reautenticar o gcloud (o deploy completo já perdeu 4 de 29 serviços por reauth)"
say "Precisa de DOIS logins: o do gcloud (deploy, IAM) e o ADC (smoke e snapshot usam a lib Python)."
say "Conta esperada: tecnologia@smartbetting.app."
so_se_confirmar "Rodar 'gcloud auth login' agora (abre o navegador)?" gcloud auth login
so_se_confirmar "Rodar 'gcloud auth application-default login' agora (abre o navegador)?" \
