[[ -n "$CONTA" ]] || { warn "Nenhuma conta ativa no gcloud."; exit 1; }
confirm "A conta ativa é a certa para mexer em IAM e deployar em $P?" || exit 1

# ── 3. Snapshot congelado do universo de odds ────────────────────────────
stage "Snapshot congelado do universo de odds (ANTES de qualquer corte)"
