mostra_e_roda "$PY" scripts/snapshot_odds_pre_corte.py || { warn "dry-run falhou"; exit 1; }
say ""
so_se_confirmar "Criar o snapshot de verdade (--apply)? Copy job, grátis, ~700 MB de armazenamento." \
  "$PY" scripts/snapshot_odds_pre_corte.py --apply
note "Anote o nome impresso em 'CRIADO': é a tabela para onde o Victor aponta os scripts de análise."
pause "Anotou o nome da tabela congelada?"

# ── 4. SQL administrativo: coluna regra_versao ───────────────────────────
stage "SQL administrativo: a coluna regra_versao do estado de sincronização (DEV e PRD)"
say "Sem a coluna, a imagem nova ABORTA o sync antes de qualquer TRUNCATE (fail-closed). É DDL: só por"
say "psycopg com o .env, nunca pela MCP do Supabase (somente leitura). Idempotente."
say "O .env é lido sem imprimir nenhum valor."
aplica_sql_admin() {
  "$PY" - <<'PYEOF'
import psycopg
from dotenv import dotenv_values

env = dotenv_values(".env")
sql = open("scripts/sql/sync_state_regra_versao.sql", encoding="utf-8").read()
for chave in ("SUPABASE_PG_URL_DEV", "SUPABASE_PG_URL_PRD"):
    with psycopg.connect(env[chave], autocommit=True, connect_timeout=15) as c:
        c.execute(sql)
        linha = c.execute(
            "select column_name, data_type from information_schema.columns "
            "where table_schema = 'futebol' and table_name = '_sync_state' "
            "and column_name = 'regra_versao'"
        ).fetchone()
        print(chave, "->", linha)
        assert linha is not None, f"coluna ausente em {chave}"
PYEOF
}
so_se_confirmar "Aplicar o SQL administrativo no DEV e no PRD (ALTER TABLE ... ADD COLUMN IF NOT EXISTS)?" \
  aplica_sql_admin
note "Esperado: duas linhas 'SUPABASE_PG_URL_* -> ('regra_versao', 'text')'."

